-- 青檐万灵册演示数据集（生成器：scripts/demo/generate_demo_data.py）
-- 目标：200 档案 / 12 项目 / 1200 捐赠 / 5 群体；仅用于演示库。
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM adoption_payment;
DELETE FROM adoption;
DELETE FROM adoption_plan;
DELETE FROM expense;
DELETE FROM donation;
DELETE FROM project_settlement;
DELETE FROM project_budget;
DELETE FROM project;
DELETE FROM visit;
DELETE FROM rescue_order;
DELETE FROM report;
DELETE FROM tnr_task;
DELETE FROM health_record;
DELETE FROM animal_status_log;
DELETE FROM animal_change_log;
DELETE FROM sighting;
DELETE FROM occurrence;
DELETE FROM animal_group;
DELETE FROM animal;
DELETE FROM notice;
DELETE FROM message;
DELETE FROM task_signup;
DELETE FROM task;
DELETE FROM volunteer;
DELETE FROM comment;
DELETE FROM follow;
DELETE FROM seq_no;
DELETE FROM sys_log;
SELECT '2023010111', '2023010111@stu.just.edu.cn',
       '$2a$10$xR/.OuYZpuECSESwC2.jt.4gZVTFxE2h8/G5j3Q8CXu6na0VqXVXe',
       '周棠', '计算机学院', 'ANIMAL_ADMIN', 'ACTIVE'
WHERE NOT EXISTS (SELECT 1 FROM sys_user WHERE user_no = '2023010111');

SELECT '2023010112', '2023010112@stu.just.edu.cn',
       '$2a$10$xR/.OuYZpuECSESwC2.jt.4gZVTFxE2h8/G5j3Q8CXu6na0VqXVXe',
       '许砚', '生物技术学院', 'ANIMAL_ADMIN', 'ACTIVE'
WHERE NOT EXISTS (SELECT 1 FROM sys_user WHERE user_no = '2023010112');

SELECT '2023010111', '周棠', '计算机学院', '2023', '2026-秋-演示'
WHERE NOT EXISTS (SELECT 1 FROM base_roster WHERE user_no = '2023010111');
SELECT '2023010112', '许砚', '生物技术学院', '2023', '2026-秋-演示'
WHERE NOT EXISTS (SELECT 1 FROM base_roster WHERE user_no = '2023010112');

SELECT u.id, 'ANIMAL_ADMIN', 'GRANTED', NOW(), u.id
FROM sys_user u
WHERE u.user_no IN ('2023010101', '2023010111', '2023010112')
  AND NOT EXISTS (SELECT 1 FROM sys_user_role r WHERE r.user_id = u.id AND r.role_code = 'ANIMAL_ADMIN');
SET @admin_a := (SELECT id FROM sys_user WHERE user_no = '2023010101' LIMIT 1);
SET @admin_b := (SELECT id FROM sys_user WHERE user_no = '2023010111' LIMIT 1);
SET @admin_c := (SELECT id FROM sys_user WHERE user_no = '2023010112' LIMIT 1);
SET @sys_admin := (SELECT id FROM sys_user WHERE user_no = '2023010102' LIMIT 1);
SET @stu_a := (SELECT id FROM sys_user WHERE user_no = '2023010173' LIMIT 1);
SET @stu_b := (SELECT id FROM sys_user WHERE user_no = '2023010103' LIMIT 1);
SET @stu_c := (SELECT id FROM sys_user WHERE user_no = '2023010104' LIMIT 1);
SET @stu_d := (SELECT id FROM sys_user WHERE user_no = '2023019001' LIMIT 1);
UPDATE project p
SET raised_amount = COALESCE((SELECT SUM(d.amount) FROM donation d
                              WHERE d.project_id = p.id AND d.status = 'VERIFIED'), 0),
    spent_amount = COALESCE((SELECT SUM(e.amount) FROM expense e
                             WHERE e.project_id = p.id AND e.status = 'APPROVED'), 0);
SELECT @stu_c, 'ACTIVE', '周三下午 / 周六上午', 18, @admin_a, NOW(), NOW(), @admin_a
WHERE NOT EXISTS (SELECT 1 FROM volunteer WHERE user_id = @stu_c);
ON DUPLICATE KEY UPDATE current_no = GREATEST(current_no, VALUES(current_no));
SET FOREIGN_KEY_CHECKS = 1;
SELECT 'qywl-demo seeded: 200 animals / 12 projects / 1200 donations / 5 groups' AS result;
