INSERT INTO project (id, project_no, name, purpose, target_type, target_amount, raised_amount, spent_amount, start_date, end_date, status, auditor_id, audit_reason, cover_file_id, deleted, created_at, updated_at, created_by) VALUES
(1, 'PRJ-2026-001', '东门草坪流浪猫绝育计划', '为东门草坪及周边流浪猫提供绝育、疫苗与术后观察费用，减少无序繁殖。', 'ANIMAL', 5000000, 0, 0, '2026-10-01', '2027-01-31', 'FUNDING', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
(2, 'PRJ-2026-002', '中心湖候鸟栖息地守护', '维护中心湖东岸的鸟类饮水点与栖息草丛，支持校园生物多样性观察。', 'GROUP', 4000000, 0, 0, '2026-09-15', '2027-02-28', 'FUNDING', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
(3, 'PRJ-2026-003', '校园流浪犬医疗救助', '用于校园流浪犬的体检、外伤处理与必要送医，保障学生与动物安全。', 'ANIMAL', 3500000, 0, 0, '2026-10-10', '2027-01-15', 'FUNDING', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
(4, 'PRJ-2026-004', '冬季猫屋保温改造', '对三个投喂点的猫屋进行保温改造，采购保温垫、防水布与冬季猫粮。', 'MIXED', 2800000, 0, 0, '2026-10-20', '2027-01-31', 'FUNDING', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
(5, 'PRJ-2026-005', '外伤猫紧急手术基金', '为外伤、骨折、感染等需要紧急手术的猫提供手术与住院费用。', 'ANIMAL', 4500000, 0, 0, '2026-09-01', '2027-03-31', 'FUNDING', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
(6, 'PRJ-2026-006', '校园 TNR 常态化行动', '支持校园 TNR 常态化：抓捕、送医、绝育、放归与术后回访。', 'MIXED', 6000000, 0, 0, '2026-08-15', '2027-06-30', 'FUNDING', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
(7, 'PRJ-2026-007', '幼猫奶粉与驱虫计划', '为幼猫采购奶粉、幼猫粮、驱虫药与基础医疗物资。', 'ANIMAL', 2200000, 0, 0, '2026-11-01', '2027-04-30', 'FUNDING', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
(8, 'PRJ-2026-008', '老校区围墙投喂点维护', '老校区围墙投喂点的日常维护、清洁与冬季补给。', 'MIXED', 2500000, 0, 0, '2026-08-01', '2026-11-15', 'PENDING_SETTLE', @admin_a, '项目资料完整，预算与目标匹配。', NULL, 0, '2026-08-01 10:00:00', '2026-11-15 16:00:00', @admin_a),
